{
  "iteration": 10,
  "pcvs": [
    {
      "name": "latent_volume",
      "expression": "x.shape[0] * x.shape[2] * x.shape[3] * x.shape[4]",
      "rationale": "Captures spatial-volume work common to both cache regimes."
    },
    {
      "name": "cached_latent_volume",
      "expression": "x.shape[0] * x.shape[2] * x.shape[3] * x.shape[4] if feat_cache is not None and feat_cache[feat_idx[0]] is not None else 0",
      "rationale": "Allows an independent volume slope for cached execution."
    },
    {
      "name": "has_cached_features",
      "expression": "int(feat_cache is not None and feat_cache[feat_idx[0]] is not None)",
      "rationale": "Captures fixed overhead from cache handling and temporal operations."
    },
    {
      "name": "mixed_stage_boundary",
      "expression": "x.shape[0] * x.shape[2] * (x.shape[3] + x.shape[4]) * (3 if feat_cache is not None and feat_cache[feat_idx[0]] is not None else 1)",
      "rationale": "Approximates combined boundary work across stages with onefold, twofold, and fourfold temporal extent."
    }
  ],
  "hypothesis": "Fourfold boundary weighting was better than onefold, twofold, or eightfold weighting. Threefold weighting tests whether combining intermediate and final temporal scales better explains the remaining spatial instruction patterns."
}
